function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 rows.';
  let total = 0;
  for (const line of nums) {
    if (!Array.isArray(line) || line.length < 1) return 'Every row needs at least one value.';
    total += line.length;
    if (line.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value is between 1 and 100000.';
  }
  if (total > 100000) return 'nums may hold at most 100000 values in all.';
  return null;
}

