function findDiagonalOrder(nums) {
  const diagonals = [];

  for (let row = nums.length - 1; row >= 0; row--) {
    for (let col = 0; col < nums[row].length; col++) {
      const index = row + col;
      if (diagonals[index] === undefined) {
        diagonals[index] = [];
      }
      diagonals[index].push(nums[row][col]);
    }
  }

  const result = [];
  for (const diagonal of diagonals) {
    for (const value of diagonal) {
      result.push(value);
    }
  }
  return result;
}

