function findDiagonalOrder(nums) {
  // Tag each entry with its position and sort: by i + j, then by row from bottom to top.
  const cells = [];
  nums.forEach((line, i) => line.forEach((v, j) => cells.push({ i, j, v })));
  cells.sort((a, b) => (a.i + a.j) - (b.i + b.j) || b.i - a.i);
  return cells.map(c => c.v);
}

