  if (size !== 'large') {
    const rows = 1 + Math.floor(rand() * 5);
    return [Array.from({ length: rows }, () => Array.from({ length: 1 + Math.floor(rand() * 5) }, value))];
  }
  const shape = Math.floor(rand() * 3);
  let rows, maxLen;
  if (shape === 0) { rows = 2000; maxLen = 8; }
  else if (shape === 1) { rows = 10; maxLen = 1900; }
  else { rows = 200; maxLen = 90; }
  return [Array.from({ length: rows }, () => Array.from({ length: 1 + Math.floor(rand() * maxLen) }, value))];
}
